script.setup:
// OGL's scene graph drives a small orrery: planets and moons are nested
// Transforms, so each one only spins around its parent.
const mod = await ctx.utils.import("https://esm.sh/ogl@1.0.11");
const O = mod.default ?? mod;
const { Renderer, Camera, Transform, Program, Mesh, Sphere, Torus, Geometry } = O;
// OGL asks the canvas for a webgl2 context and gets the scene's own one back.
// Its constructor also sizes and styles the canvas; put both back for the runtime.
const style = ctx.canvas.getAttribute("style"), [cw, ch] = ctx.resolution;
const renderer = new Renderer({ canvas: ctx.canvas, webgl: 2, dpr: 1, width: cw, height: ch });
if (style === null) ctx.canvas.removeAttribute("style"); else ctx.canvas.setAttribute("style", style);
const gl = renderer.gl;
gl.clearColor(0.015, 0.016, 0.03, 1);
const camera = new Camera(gl, { fov: 38, near: 0.1, far: 200 });
const scene = new Transform();
const vertex = `#version 300 es
in vec3 position; in vec3 normal; in vec2 uv;
uniform mat4 modelMatrix, viewMatrix, projectionMatrix;
out vec3 vN; out vec3 vW; out vec2 vUv;
void main() { vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; vN = mat3(modelMatrix) * normal; vUv = uv; gl_Position = projectionMatrix * viewMatrix * w; }`;
const lit = `#version 300 es
precision highp float;
in vec3 vN; in vec3 vW; in vec2 vUv; out vec4 outColor;
uniform vec3 uColor, uColor2, cameraPosition; uniform float uBands, uTime;
void main() {
  vec3 n = normalize(vN), l = normalize(-vW), v = normalize(cameraPosition - vW);
  float d = max(dot(n, l), 0.0);
  // Latitude bands give gas giants some texture.
  float band = 0.5 + 0.5 * sin(vUv.y * uBands * 6.283 + sin(vUv.x * 12.566 + uTime * 0.3) * 0.6);
  vec3 base = mix(uColor, uColor2, band);
  float rim = pow(1.0 - max(dot(n, v), 0.0), 3.0);
  vec3 c = base * (0.04 + 1.1 * d) + rim * d * base * 0.8 + pow(max(dot(n, normalize(l + v)), 0.0), 40.0) * 0.25;
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`;
const sunFrag = `#version 300 es
precision highp float;
in vec3 vN; in vec3 vW; in vec2 vUv; out vec4 outColor;
uniform vec3 cameraPosition; uniform float uTime;
void main() {
  vec3 n = normalize(vN), v = normalize(cameraPosition - vW);
  float f = max(dot(n, v), 0.0);
  float g = 0.5 + 0.5 * sin(vUv.x * 40.0 + uTime) * sin(vUv.y * 30.0 - uTime * 0.7);
  vec3 c = mix(vec3(1.0, 0.35, 0.05), vec3(1.0, 0.85, 0.45), f * 0.8 + g * 0.2);
  outColor = vec4(c * (0.8 + 0.6 * f), 1.0);
}`;
const flatFrag = `#version 300 es
precision highp float; out vec4 outColor; uniform vec3 uColor;
void main() { outColor = vec4(uColor, 1.0); }`;
const programs = [];
const prog = (fragment, uniforms = {}) => {
  const p = new Program(gl, { vertex, fragment, uniforms: { uTime: { value: 0 }, ...uniforms } });
  programs.push(p);
  return p;
};
const planetProg = (a, b, bands) => prog(lit, { uColor: { value: a }, uColor2: { value: b }, uBands: { value: bands } });
const sphere = new Sphere(gl, { radius: 1, widthSegments: 48, heightSegments: 32 });
const sun = new Mesh(gl, { geometry: sphere, program: prog(sunFrag) });
sun.scale.set(1.3);
sun.setParent(scene);
const orbitProg = prog(flatFrag, { uColor: { value: [0.16, 0.18, 0.28] } });
const bodies = [];
const planet = ({ dist, size, speed, tilt, a, b, bands, ring, moons = [] }) => {
  size *= 1.5; // not to scale: big enough to read
  const pivot = new Transform(); pivot.rotation.z = tilt; pivot.setParent(scene);
  const orbit = new Transform(); orbit.setParent(pivot);
  const line = new Mesh(gl, { geometry: new Torus(gl, { radius: dist, tube: 0.008, radialSegments: 4, tubularSegments: 180 }), program: orbitProg });
  line.rotation.x = Math.PI / 2; line.setParent(pivot);
  const body = new Mesh(gl, { geometry: sphere, program: planetProg(a, b, bands) });
  body.position.x = dist; body.scale.set(size); body.setParent(orbit);
  if (ring) {
    const r = new Mesh(gl, { geometry: new Torus(gl, { radius: size * 1.8, tube: size * 0.4, radialSegments: 2, tubularSegments: 96 }), program: planetProg([0.75, 0.66, 0.5], [0.45, 0.38, 0.3], 3) });
    const holder = new Transform(); holder.position.x = dist; holder.rotation.z = 0.35; holder.setParent(orbit);
    r.scale.set(1, 1, 0.06); r.rotation.x = Math.PI / 2; r.setParent(holder);
  }
  bodies.push({ orbit, body, speed, phase: Math.random() * 6.28 });
  moons.forEach((m) => {
    const mo = new Transform(); mo.setParent(body);
    const moon = new Mesh(gl, { geometry: sphere, program: planetProg([0.7, 0.7, 0.72], [0.5, 0.5, 0.55], 2) });
    moon.position.x = m.dist; moon.scale.set(m.size); moon.setParent(mo);
    bodies.push({ orbit: mo, speed: m.speed, phase: Math.random() * 6.28 });
  });
};
planet({ dist: 2.4, size: 0.18, speed: 1.6, tilt: 0.05, a: [0.75, 0.55, 0.45], b: [0.55, 0.4, 0.35], bands: 1 });
planet({ dist: 3.6, size: 0.32, speed: 1.0, tilt: -0.04, a: [0.15, 0.4, 0.85], b: [0.3, 0.7, 0.45], bands: 2, moons: [{ dist: 2.2, size: 0.28, speed: 3 }] });
planet({ dist: 5.2, size: 0.26, speed: 0.7, tilt: 0.08, a: [0.85, 0.35, 0.2], b: [0.6, 0.25, 0.15], bands: 1.5 });
planet({ dist: 7.4, size: 0.62, speed: 0.4, tilt: -0.06, a: [0.9, 0.75, 0.5], b: [0.65, 0.4, 0.25], bands: 7, ring: true, moons: [{ dist: 2.6, size: 0.12, speed: 2.2 }, { dist: 3.3, size: 0.09, speed: 1.5 }] });
planet({ dist: 9.6, size: 0.45, speed: 0.25, tilt: 0.1, a: [0.35, 0.65, 0.9], b: [0.25, 0.45, 0.8], bands: 5 });
// Stars: a points mesh on a big sphere.
const stars = new Float32Array(2400 * 3);
for (let i = 0; i < 2400; i++) {
  const z = Math.random() * 2 - 1, t = Math.random() * 6.283, r = Math.sqrt(1 - z * z) * 60;
  stars.set([r * Math.cos(t), z * 60, r * Math.sin(t)], i * 3);
}
const starProg = new Program(gl, {
  vertex: `#version 300 es
in vec3 position; uniform mat4 modelViewMatrix, projectionMatrix; out float vB;
void main() { vB = fract(sin(dot(position, vec3(12.9, 78.2, 37.7))) * 43758.5); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); gl_PointSize = 1.0 + 2.0 * vB; }`,
  fragment: `#version 300 es
precision highp float; in float vB; out vec4 outColor; void main() { outColor = vec4(vec3(0.35 + 0.65 * vB), 1.0); }`,
});
new Mesh(gl, { mode: gl.POINTS, geometry: new Geometry(gl, { position: { size: 3, data: stars } }), program: starProg }).setParent(scene);
Object.assign(ctx.state, { renderer, camera, scene, bodies, sun, programs, t: 0,
  orbit: ctx.utils.createOrbitCamera({ distance: 20, theta: 0.4, phi: 1.1, fov: 38, near: 0.1, far: 200, minDistance: 3, maxDistance: 60 }) });

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution;
// Set the size directly: renderer.setSize would also restyle the canvas.
s.renderer.width = w; s.renderer.height = h;
// The shared orbit camera drives OGL's camera.
s.orbit.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
s.camera.perspective({ fov: s.orbit.fov, aspect: w / h });
s.camera.position.set(...s.orbit.getEye());
s.camera.lookAt(s.orbit.getTarget());
s.t += ctx.dt * u.u_speed;
for (const b of s.bodies) b.orbit.rotation.y = b.phase + s.t * b.speed;
for (const b of s.bodies) if (b.body) b.body.rotation.y = s.t * 2;
s.sun.rotation.y = s.t * 0.2;
for (const p of s.programs) p.uniforms.uTime.value = ctx.time;
s.renderer.render({ scene: s.scene, camera: s.camera });
